#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
"""Regenerate the checked-in presentation blit and NV12 CSC SPIR-V."""
import pathlib
import struct
import subprocess
import tempfile

directory = pathlib.Path(__file__).resolve().parent


def emit(name, prefix):
    output = [
        '/* SPDX-License-Identifier: MIT\n * Generated by shaders/generate.py. */\n',
        f'#ifndef TGD3D_{prefix.upper()}_SPV_H\n#define TGD3D_{prefix.upper()}_SPV_H\n',
        '#include <stdint.h>\n',
    ]
    with tempfile.TemporaryDirectory() as temporary:
        for stage in ('vert', 'frag'):
            binary = pathlib.Path(temporary) / (stage + '.spv')
            subprocess.run(['glslangValidator', '-V', '--target-env', 'vulkan1.1',
                            '-o', str(binary), str(directory / (name + '.' + stage))],
                           check=True)
            subprocess.run(['spirv-val', '--target-env', 'vulkan1.1', str(binary)],
                           check=True)
            code = binary.read_bytes()
            words = struct.unpack('<' + 'I' * (len(code) // 4), code)
            output.append(f'static const uint32_t tgd3d_{prefix}_{stage}[] = {{\n')
            for i in range(0, len(words), 8):
                output.append('   ' + ', '.join('0x%08x' % w for w in words[i:i+8]) + ',\n')
            output.append('};\n')
    output.append('#endif\n')
    (directory / (prefix + '_spv.h')).write_text(''.join(output))


emit('blit', 'blit')
emit('nv12', 'nv12')
